import{_ as t,o,c as a,a2 as d}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"Not Included","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/not-included.md","filePath":"introduction/not-included.md"}'),s={name:"introduction/not-included.md"};function r(n,e,i,c,h,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="not-included" tabindex="-1">Not Included <a class="header-anchor" href="#not-included" aria-label="Permalink to &quot;Not Included&quot;">​</a></h1><p>skapi-swift has every feature of skapi-py, plus the ones an app on a phone or a Mac needs and a Python program does not: sessions kept in the Keychain, a remembered encryption key for this device, and reconnecting when the app returns to the foreground. A few skapi-js features are left out, because the platform has no equivalent or because they need something today&#39;s backend does not offer.</p><table tabindex="0"><thead><tr><th>skapi-js has</th><th>why skapi-swift leaves it out</th></tr></thead><tbody><tr><td>Admin and project-owner methods (managing users, invitations, newsletters, hosting, project settings)</td><td>They belong to the dashboard on <a href="https://www.skapi.com" target="_blank" rel="noreferrer">skapi.com</a> and to the project owner, not to the users of your app. skapi-py leaves them out for the same reason.</td></tr><tr><td>Web push notifications: <code>subscribeNotification()</code>, <code>unsubscribeNotification()</code>, <code>vapidPublicKey()</code>, <code>pushNotification()</code></td><td>They use the browser&#39;s Push API with VAPID keys and a service worker. iOS and macOS deliver notifications through Apple&#39;s push service (APNs), which today&#39;s backend does not send to.</td></tr><tr><td>WebRTC video and voice calls: <code>connectRTC()</code>, <code>closeRTC()</code></td><td>They need a large native WebRTC library. <a href="/realtime/connecting.html">Realtime messages</a> are included.</td></tr><tr><td>HTML form helpers: passing a form element or a submit event to a method, and the form <code>response</code> and <code>redirect</code> options</td><td>There is no web page and no DOM in an app. Pass your values as <a href="/introduction/getting-started.html#json-values"><code>JSON</code></a> instead.</td></tr><tr><td>The browser Project ID prompt</td><td>An app is built with its Project ID: pass it to <code>Skapi(projectId:)</code>.</td></tr><tr><td>Upload and download progress callbacks</td><td>Not in this release. Uploads and downloads return when they are done.</td></tr><tr><td><code>forwardRequest</code> with <code>responseType: &quot;response&quot;</code></td><td>The request is relayed and its answer stored by Skapi&#39;s server, so there is no live <code>Response</code> to hand over. The destination&#39;s status code is in <a href="/api-bridge/forward-request.html#request-history"><code>forwardRequestHistory</code></a>. skapi-py leaves it out for the same reason.</td></tr></tbody></table><h2 id="what-skapi-swift-adds-over-skapi-py" tabindex="-1">What skapi-swift adds over skapi-py <a class="header-anchor" href="#what-skapi-swift-adds-over-skapi-py" aria-label="Permalink to &quot;What skapi-swift adds over skapi-py&quot;">​</a></h2><p>These skapi-js features are web-only in skapi-js and left out of skapi-py. skapi-swift has a native counterpart for each:</p><table tabindex="0"><thead><tr><th>skapi-js</th><th>skapi-swift</th></tr></thead><tbody><tr><td>sessions in <code>localStorage</code></td><td>sessions in the <a href="/introduction/getting-started.html#keeping-users-signed-in">Keychain</a>, one Keychain service per project</td></tr><tr><td>the encryption key remembered in IndexedDB</td><td>the encryption key remembered in the Keychain, on this device only: <a href="/database/encryption.html#remembering-this-device">Remembering this device</a></td></tr><tr><td>reconnecting when a tab becomes visible or the browser goes back online</td><td>reconnecting when the app returns to the foreground or the network comes back: <a href="/introduction/getting-started.html#app-lifecycle">App lifecycle</a></td></tr><tr><td>uploading <code>File</code> objects from a page</td><td>uploading from a file URL, a path, <code>Data</code> or an <code>InputStream</code>: <a href="/database/files.html#uploading-with-a-record">Files</a></td></tr></tbody></table>',6)])])}const f=t(s,[["render",r]]);export{u as __pageData,f as default};
